A custom hook is a function whose name starts with `use` and which calls other hooks:

```jsx
function useDebounced(value, ms) {
  const [debounced, setDebounced] = useState(value);
  useEffect(() => {
    const id = setTimeout(() => setDebounced(value), ms);
    return () => clearTimeout(id);
  }, [value, ms]);
  return debounced;
}
```

Use it as `const q = useDebounced(input, 300);` and fetch when `q` changes. The cleanup function cancels the previous timer, which is what makes it a debounce.

How do I implement a linked list node insertion and traversal in C?

```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Node { int v; struct Node *next; } Node;

Node *push_front(Node *head, int v) {
    Node *n = malloc(sizeof *n);
    if (!n) exit(1);
    n->v = v; n->next = head;
    return n;
}

int main(void) {
    Node *head = NULL;
    for (int i = 1; i <= 4; i++) head = push_front(head, i);
    for (Node *p = head; p; p = p->next) printf("%d ", p->v);
    printf("\n");
    while (head) { Node *t = head->next; free(head); head = t; }
    return 0;
}
```

